import {products} from './data.js?v=6';
import {installShell} from './ui.js?v=6';
installShell();
document.querySelector('#product-stories').innerHTML=products.map(p=>`<section id="${p.id}" class="product-chapter"><div class="product-chapter-head"><div><span class="eyebrow">${p.kicker}</span><h2>${p.name}</h2><span class="product-en">${p.en.toUpperCase()}</span></div><p>${p.description}</p></div><div class="product-scene"><img src="${p.image}" alt="${p.name}概念设计效果图" loading="lazy">${p.hotspots.map((h,i)=>`<button class="hotspot" style="--x:${h.x}%;--y:${h.y}%" data-product="${p.id}" data-hotspot="${i}" aria-label="${h.title}" aria-expanded="${i===0}" aria-controls="${p.id}-features">${i+1}</button>`).join('')}<span class="product-scene-label">点击节点，发现声音与产品的连接。</span></div><div class="hotspot-content" id="${p.id}-features" role="region" aria-label="产品功能说明" aria-live="polite"><h3><span>01</span>${p.hotspots[0].title}</h3><p>${p.hotspots[0].text}</p></div><div class="product-footnote"><span>${p.material} · 概念设计</span><a href="lab.html">体验声音可视化 ↗</a></div></section>`).join('');
document.querySelector('#cabin').insertAdjacentHTML('beforeend',`<div class="product-structure"><img src="assets/cabin-structure.webp" alt="雨林声栖小屋的分层结构设计图" loading="lazy"><div><span class="eyebrow">DESIGNED AROUND LISTENING</span><h3>一座小屋，<br>六个感知自然的入口。</h3><p>从声音的播放，到光影的转译，再到物种故事与在地合作。每一个功能，都让一次聆听走得更深一点。</p><ol><li>声音播放系统</li><li>声音可视化装置</li><li>定向声场系统</li><li>科普信息</li><li>联名展示</li><li>交互控制面板</li></ol></div></div>`);
document.querySelectorAll('.hotspot').forEach(b=>b.addEventListener('click',()=>{const p=products.find(p=>p.id===b.dataset.product),i=+b.dataset.hotspot,h=p.hotspots[i],region=document.getElementById(p.id+'-features');region.querySelector('h3').innerHTML=`<span>0${i+1}</span>${h.title}`;region.querySelector('p').textContent=h.text;document.querySelectorAll(`[data-product="${p.id}"]`).forEach(btn=>btn.setAttribute('aria-expanded',String(btn===b)))}));
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&!matchMedia('(pointer: coarse)').matches)for(const scene of document.querySelectorAll('.product-scene')){scene.addEventListener('pointermove',e=>{const r=scene.getBoundingClientRect();scene.style.setProperty('--px',((e.clientX-r.left)/r.width-.5)*3+'deg');scene.style.setProperty('--py',-((e.clientY-r.top)/r.height-.5)*3+'deg')});scene.addEventListener('pointerleave',()=>{scene.style.setProperty('--px','0deg');scene.style.setProperty('--py','0deg')})}
if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());

if(!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion-ready');const reveal=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('is-visible');reveal.unobserve(e.target)}},{threshold:.08});document.querySelectorAll('.product-chapter').forEach(el=>reveal.observe(el));}
